import assert from 'node:assert/strict'
import { Readable, PassThrough } from 'node:stream'
import { resolve } from 'node:path'
import { pathToFileURL } from 'node:url'
const root = resolve(import.meta.dir, '../..')
const modules = await Promise.all(['before', 'after'].map(async (version) => {
  const base = version === 'before' ? resolve(import.meta.dir, 'before') : root
  return {
    native: (await import(pathToFileURL(resolve(base, 'packages/runtime/src/native-transport.ts')).href)).NativeTransport,
    rpc: await import(pathToFileURL(resolve(base, 'packages/contracts/src/rpc-wire.ts')).href),
    limits: (await import(pathToFileURL(resolve(base, 'packages/contracts/src/rpc.ts')).href)).rpcLimits(),
  }
}))
const ready = Buffer.from(JSON.stringify({v:1,event:'ready',abi:1,cef:'154.0.34'})+'\n')
const shutdown = Buffer.from('{"v":1,"event":"shutdown"}\n')
function chunks(events:number, message:string, size:number) {
  const frames = Array.from({length:events}, (_,i)=> Buffer.from(JSON.stringify({v:1,event:'view.title',target:1,data:{title:message,index:i}})+'\n'))
  const bytes=Buffer.concat([ready,...frames,shutdown])
  const parts:Buffer[]=[]
  for(let i=0;i<bytes.length;i+=size) parts.push(bytes.subarray(i,i+size))
  return {parts,events,bytes:bytes.length,chunkBytes:size}
}
const typical=chunks(4096,'fixture title',16384)
const fragmented=chunks(8,'λ'.repeat(24000),64)
const value=Array.from({length:128},(_,i)=>({name:'entry-'+i,path:'app://ui/file-'+i,flags:[true,false],size:i}))
const packet=modules[0]!.rpc.encodeRpc({type:'success',id:1,value},modules[0]!.limits)
const tiny=modules[0]!.rpc.encodeRpc({type:'success',id:1,value:null},modules[0]!.limits)
async function native(index:number, input:ReturnType<typeof chunks>) {
  let seen=0
  const stream=Readable.from(input.parts)
  const transport=new modules[index]!.native(stream,new PassThrough())
  transport.onEvent((event: {event:string;data?:Record<string,unknown>})=>{
    if(event.event==='view.title') { assert.equal(event.data?.index,seen); seen++ }
  })
  await transport.closed
  assert.equal(transport.failure,null)
  assert.equal(seen,input.events)
}
function decode(index:number, bytes:Uint8Array, iterations:number, expected:boolean) {
  let count=0
  for(let i=0;i<iterations;i++) {
    const result=modules[index]!.rpc.decodeRpc(bytes,modules[index]!.limits)
    assert.equal(result.type,'success')
    if(expected) count+=result.value.length
    else assert.equal(result.value,null)
  }
  assert.equal(count,expected?iterations*128:0)
}
async function roundTrips(index:number) {
  const input=new PassThrough(),output=new PassThrough()
  const transport=new modules[index]!.native(input,output)
  output.on('data',(bytes:Buffer)=>{
    const request=JSON.parse(bytes.toString())
    input.write(JSON.stringify({v:1,id:request.id,ok:true,value:request.args.n})+'\n')
  })
  input.write(ready)
  await transport.ready
  try {
    for(let n=0;n<512;n++) assert.equal(await transport.call('diagnostics',{n}),n)
  } finally { input.write(shutdown); await transport.closed }
  assert.equal(transport.failure,null)
}
const cases = [
  {name:'native-sequential-roundtrip',run:(i:number)=>roundTrips(i),parameters:{roundTrips:512}},
  {name:'native-coalesced',run:(i:number)=>native(i,typical),parameters:{events:typical.events,inputBytes:typical.bytes,chunkBytes:typical.chunkBytes}},
  {name:'native-fragmented-utf8',run:(i:number)=>native(i,fragmented),parameters:{events:fragmented.events,inputBytes:fragmented.bytes,chunkBytes:fragmented.chunkBytes}},
  {name:'rpc-json-decode',run:(i:number)=>decode(i,packet,256,true),parameters:{iterations:256,packetBytes:packet.length,records:128}},
  {name:'rpc-control-decode',run:(i:number)=>decode(i,tiny,4096,false),parameters:{iterations:4096,packetBytes:tiny.length}},
]
const workloads=[]
for(const item of cases) {
  const raw:{before:number[];after:number[]}={before:[],after:[]}
  for(let trial=-1;trial<8;trial++) {
    for(const i of (trial%2===0?[0,1]:[1,0])) {
      const start=performance.now()
      await item.run(i)
      const elapsed=performance.now()-start
      if(trial>=0) raw[i===0?'before':'after'].push(elapsed)
    }
  }
  const median=(a:number[])=>{const b=[...a].sort((a,b)=>a-b);return (b[3]!+b[4]!)/2}
  const result={name:item.name,parameters:item.parameters,rawMs:raw,medianMs:{before:median(raw.before),after:median(raw.after)}}
  workloads.push(result)
  console.log(JSON.stringify({name:result.name,medianMs:result.medianMs}))
}
const sourcePaths=['packages/runtime/src/native-transport.ts','packages/contracts/src/rpc-wire.ts','packages/contracts/src/stream-link.ts','packages/contracts/src/streams.ts','packages/contracts/src/rpc-channel.ts','packages/client/src/rpc-port.ts']
const hashes:Record<string,{before:string;after:string}>={}
for(const file of sourcePaths) {
  const digest=async(base:string)=>new Bun.CryptoHasher('sha256').update(await Bun.file(resolve(base,file)).arrayBuffer()).digest('hex')
  hashes[file]={before:await digest(resolve(import.meta.dir,'before')),after:await digest(root)}
}
await Bun.write(resolve(import.meta.dir,'measurements.json'),JSON.stringify({schema:1,bun:Bun.version,platform:process.platform,arch:process.arch,baselineCommit:(await Bun.file(resolve(import.meta.dir,'base.txt')).text()).trim(),method:'One warmup, eight measured trials alternating before/after. Same process; protocol peers not native CEF. No quiet-machine or thermal gate. No desktop performance claim.',sourceHashes:hashes,workloads},null,2)+'\n')
